import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
handshakes = list(map(int, data[1:]))

if n == 1:
    if handshakes[0] == 0:
        print("Possible")
        print("1")
    else:
        print("Impossible")
else:
    if sum(handshakes) % 3 != 0:
        print("Impossible")
    else:
        order = []
        available = [True] * n
        handshake_count = [0] * n

        for i in range(n):
            while handshake_count[i] < handshakes[i]:
                for j in range(n):
                    if available[j] and handshake_count[j] < handshakes[j]:
                        handshake_count[i] += 1
                        handshake_count[j] += 1
                        available[j] = False
                        break
                else:
                    print("Impossible")
                    exit()
            order.append(i + 1)
            available[i] = False

        print("Possible")
        print(" ".join(map(str, order)))
